// "Import from my Excel workbook": turn the typed-in values of a <Class>-DPS-Calculator.xlsx (Inputs / ArtifactsInput / CompanionsInput sheets) into a FormState.
//
// Everything here runs in the browser; the file is never uploaded (the only network call is the optional fetch of the CLASS SCHEMA, which carries no user data).
// Where each engine input lives in the workbook comes from `xlsx_map.json` (generated by web/scripts/gen_xlsx_map.py from the builders' own layout constants).
// Only literal cell values are read (cached results for formula cells, when the file has them): the derived/computed cells are never needed.
import map from "./xlsx_map.json";
import type { ArtifactLine, ArtifactSchema, ArtifactsState, ClassSchema, EquippedState, Field, FormState, Scalar, Values } from "../types";
import { XlsxBook, XlsxError, colLetters, type Cell, type XlsxSheet } from "./xlsx_read";
import { defaultFor, isApplicable, normalizeState, parseNumber, rangeText, sharedKeys } from "./schemaForm";
import { NOT_UNLOCKED, NO_STAT, artifactInfo, blankLine, defaultStarFor, emptyArtifacts, lineCount, normalizeSlots, parseStar, EMPTY_SLOT } from "./artifacts";
import { STATIC_POTENTIAL_TABLES } from "./artifactPotentials";
import { COMPANION_NONE, COMPANION_MAX_LEVEL, emptyCompanions, type CompanionsState } from "./companions";
import { NONE_STAT as CUBE_NONE, blankRow, isConfigured, type CubesState, type GearLine, type GearRowState } from "./cubes";

export { XlsxError } from "./xlsx_read";

// ---- the generated map ---------------------------------------------------------------------------------------------------------------------------
export interface ClassMap {
  name: string;
  title: string;
  inputs: {
    sheet: string;
    headerRow: number;
    firstCol: number;
    contentTypes: string[];
    level: string;
    contentType: string;
    perContent: Record<string, number>;
    slotRows: number[];
    noneLabel: string;
  };
  artifacts: { sheet: string; starCol: number; lineCols: [number, number][]; rows: Record<string, { name: string; row: number }> };
  companions: { sheet: string; levelCol: number; rows: Record<string, number>; firstRow: number };
  /** PotentialCubes: the gear table (one row per slot x potential type); columns are 1-based. */
  cubes: {
    sheet: string;
    headerRow: number;
    firstRow: number;
    lastRow: number;
    slotCol: number;
    typeCol: number;
    rarityCol: number;
    pityCol: number;
    lineCols: [number, number][]; // (stat, value) of lines 1 / 2 / 3
    headers: string[];
  };
}

/** The class-independent cube tables (a copy of GET .../cubes/meta, generated by gen_xlsx_map.py from the fixtures; a test keeps it equal to them), so an import
 *  needs no API call and also works for the classes whose Cubes tab is not available yet. */
export interface CubeTables {
  slots: { key: string; label: string }[];
  potentialTypes: string[];
  rarities: { key: string; label: string }[];
  noneStat: string;
  stats: string[];
  statsBySlot: Record<string, string[]>;
  pityCaps: Record<string, Record<string, number>>; // potential type -> rarity -> cubes that force the upgrade (0 = top tier)
  maxPity: number;
  maxLineValue: number;
}

export const XLSX_MAP = (map as unknown as { classes: Record<string, ClassMap> }).classes;
export const CUBE_TABLES = (map as unknown as { cubeTables: CubeTables }).cubeTables;

export interface ImportNote {
  where: string; // "Inputs!C9", "ArtifactsInput", "file"
  message: string;
  field?: string; // engine key
  contentType?: string;
}

export interface ImportSummary {
  classId: string;
  className: string;
  detected: "title" | "chosen";
  fileTitle: string | null;
  level: number | null;
  contentType: string; // the content type the app opens on (the workbook's selected one when it was imported)
  /** content type -> number of cells that held a value (the rest of its fields stay at the app defaults) */
  valuesPerContent: Record<string, number>;
  skippedContentTypes: string[]; // columns that exist in the schema but have no values (left to the defaults) or no column in the file
  /** equipped artifacts per content type (only the content types that have any), by display name ("Name (star)"): they become that content type's "Equipped artifacts" (<= 4: the workbook has 4 slot rows) */
  loadouts: Record<string, string[]>;
  starsRead: number; // artifacts whose Star Level cell was read (every artifact, not only the equipped ones)
  linesRead: number; // potential lines (rarity + stat) read from ArtifactsInput
  companionChoices: Record<string, string>;
  companionLevels: { name: string; level: number }[];
  /** PotentialCubes: true when the sheet was found and read */
  cubesRead: boolean;
  cubePieces: number; // (slot, potential type) rows with at least one line
  cubeLines: number; // lines (stat + value) read in all rows
  cubeRows: number; // rows that hold anything (a rarity above normal, a pity count or a line) = the entries of `state.cubes`
  formulaCellsSkipped: number;
}

export interface ImportResult {
  state: FormState;
  warnings: ImportNote[];
  ignored: ImportNote[];
  summary: ImportSummary;
}

export interface ImportOptions {
  classChosen?: boolean; // the class was picked by the user, not detected from the file
}

// ---- class detection -----------------------------------------------------------------------------------------------------------------------------
const norm = (s: string) => s.replace(/[‐-―−]/g, "-").replace(/\s+/g, " ").trim().toLowerCase();

/** Class id from the workbook's Inputs!A1 title ("Shadower — DPS Calculator Inputs"); null when it is not one of ours. */
export function detectClass(book: XlsxBook): { classId: string | null; title: string | null } {
  const sheet = book.sheet("Inputs");
  const raw = sheet?.at(1, 1)?.value;
  const title = typeof raw === "string" && raw.trim() ? raw.trim() : null;
  if (!title) return { classId: null, title };
  const t = norm(title);
  for (const [id, m] of Object.entries(XLSX_MAP)) if (norm(m.title) === t) return { classId: id, title };
  return { classId: null, title };
}

// ---- cell coercion -------------------------------------------------------------------------------------------------------------------------------
const isBlank = (c: Cell | null): boolean => !c || c.value === null || (typeof c.value === "string" && c.value.trim() === "");
const show = (c: Cell): string => (typeof c.value === "string" ? `"${c.value}"` : String(c.value));
const ref = (col: number, row: number) => `${colLetters(col)}${row}`;

interface Ctx {
  warnings: ImportNote[];
  ignored: ImportNote[];
  formulaSkipped: number;
}

/** Read one cell as the schema field's value: `{ blank: true }` when there is nothing usable, else the typed value (out-of-range numbers are kept and flagged). */
function coerce(field: Field, cell: Cell | null, where: string, ct: string | undefined, ctx: Ctx): { blank: true } | { blank: false; value: Scalar } {
  const note = (message: string): ImportNote => ({ where, message: `${field.label}: ${message}`, field: field.key, contentType: ct });
  if (isBlank(cell)) {
    if (cell && cell.formula && cell.value === null && !cell.error) ctx.formulaSkipped++;
    if (cell?.error) ctx.ignored.push(note(`cell shows the Excel error ${cell.error}; default used`));
    return { blank: true };
  }
  const c = cell as Cell;
  if (field.type === "int" || field.type === "float") {
    let n: number;
    if (typeof c.value === "number") n = c.value;
    else if (typeof c.value === "string") {
      const text = c.value.trim().replace(/%$/, "").trim();
      const p = parseNumber(text, field.type === "int" ? "float" : field.type); // bounds are checked below (kept as typed + flagged)
      if (!p.ok || p.value === null) {
        ctx.warnings.push(note(`${show(c)} is not a number; default used`));
        return { blank: true };
      }
      n = p.value;
    } else {
      ctx.warnings.push(note(`${show(c)} is not a number; default used`));
      return { blank: true };
    }
    if (!Number.isFinite(n)) {
      ctx.warnings.push(note("not a finite number; default used"));
      return { blank: true };
    }
    if (field.type === "int" && !Number.isInteger(n)) ctx.warnings.push(note(`${n} is not a whole number (kept as typed; the calculator will flag it)`));
    else if ((field.min != null && n < field.min) || (field.max != null && n > field.max)) {
      ctx.warnings.push(note(`${n} is outside the allowed range ${rangeText(field)} (kept as typed; the calculator will flag it)`));
    }
    return { blank: false, value: n };
  }
  if (field.type === "enum") {
    const s = String(c.value).trim();
    const opt = (field.options ?? []).find((o) => o === s) ?? (field.options ?? []).find((o) => norm(o) === norm(s));
    if (!opt) {
      ctx.warnings.push(note(`${show(c)} is not one of ${(field.options ?? []).join(" / ")}; default used`));
      return { blank: true };
    }
    return { blank: false, value: opt };
  }
  // text (Chapter-Stage "28-9" / "28" / "80")
  if (typeof c.value === "number") {
    if (c.value >= 1000) {
      ctx.warnings.push(note(`${c.value} looks like a date that Excel made out of "28-9"-style text; retype it as text (e.g. 28-9). Default used`));
      return { blank: true };
    }
    return { blank: false, value: String(c.value) };
  }
  return { blank: false, value: String(c.value).trim() };
}

function level(schema: ClassSchema, sheet: XlsxSheet, cellRef: string, ctx: Ctx): number | null {
  const field = schema.fields.find((f) => f.key === "level");
  const cell = sheet.get(cellRef);
  if (!field || !cell) return null;
  const r = coerce(field, cell, `Inputs!${cellRef}`, undefined, ctx);
  return !r.blank && typeof r.value === "number" ? r.value : null;
}

// ---- the import ----------------------------------------------------------------------------------------------------------------------------------
const GENERIC_STAR = (s: Scalar | undefined): number | string | null => {
  if (s === null || s === undefined) return null;
  if (typeof s === "number") return s;
  const t = String(s).trim();
  if (norm(t) === norm(NOT_UNLOCKED)) return NOT_UNLOCKED;
  return /^\d+$/.test(t) ? Number(t) : null;
};

/** Map a parsed workbook to the app's FormState for ``schema``'s class.  Never throws for odd VALUES (they become warnings); throws XlsxError("missing_part")
 *  when the workbook has no Inputs sheet at all. */
export function importWorkbook(book: XlsxBook, schema: ClassSchema, opts: ImportOptions = {}): ImportResult {
  const cm = XLSX_MAP[schema.class_id];
  if (!cm) throw new XlsxError("not_xlsx", `No workbook layout is known for the class "${schema.class_id}".`);
  const inp = book.sheet(cm.inputs.sheet);
  if (!inp) throw new XlsxError("missing_part", `This workbook has no "${cm.inputs.sheet}" sheet, so it is not a ${cm.name} calculator.`);
  const ctx: Ctx = { warnings: [], ignored: [], formulaSkipped: 0 };
  const det = detectClass(book);

  // content-type columns (one per content type, C..L), identified by their header names rather than by position
  const columns = new Map<string, number>();
  for (let col = cm.inputs.firstCol; col < cm.inputs.firstCol + cm.inputs.contentTypes.length; col++) {
    const h = inp.at(cm.inputs.headerRow, col);
    if (isBlank(h)) continue;
    const name = String(h!.value).trim();
    const known = schema.content_types.find((c) => c === name) ?? schema.content_types.find((c) => norm(c) === norm(name));
    if (known && !columns.has(known)) columns.set(known, col);
    else if (!known) ctx.ignored.push({ where: ref(col, cm.inputs.headerRow), message: `Column "${name}" is not a content type of this class; ignored` });
    else ctx.ignored.push({ where: ref(col, cm.inputs.headerRow), message: `Column "${name}" repeats a content type already read from column ${colLetters(columns.get(known)!)}; ignored` });
  }
  if (!columns.size) throw new XlsxError("not_xlsx", `The Inputs sheet has no content-type header row (row ${cm.inputs.headerRow}); this does not look like a ${cm.name} calculator.`);

  const sharedKeySet = new Set(sharedKeys(schema));
  const perContent: Record<string, Values> = {};
  const valuesPerContent: Record<string, number> = {};
  const skipped: string[] = [];

  for (const ct of schema.content_types) {
    const col = columns.get(ct);
    if (col === undefined) {
      skipped.push(ct);
      continue;
    }
    const vals: Values = {};
    let read = 0;
    for (const f of schema.fields) {
      if (f.computed || f.key === "content_type" || sharedKeySet.has(f.key)) continue;
      const row = cm.inputs.perContent[f.key];
      if (row === undefined) {
        vals[f.key] = defaultFor(f, ct);
        continue;
      }
      const where = ref(col, row);
      const cell = inp.at(row, col);
      if (!isApplicable(f, ct)) {
        vals[f.key] = null;
        if (!isBlank(cell)) ctx.ignored.push({ where, message: `${f.label} does not apply to ${ct} (cell has ${show(cell as Cell)}); ignored`, field: f.key, contentType: ct });
        continue;
      }
      const r = coerce(f, cell, where, ct, ctx);
      if (r.blank) vals[f.key] = defaultFor(f, ct);
      else {
        vals[f.key] = r.value;
        read++;
      }
    }
    if (read === 0) {
      skipped.push(ct);
      continue;
    }
    perContent[ct] = vals;
    valuesPerContent[ct] = read;
  }
  if (!Object.keys(perContent).length) throw new XlsxError("not_xlsx", `The Inputs sheet has no values in its content-type columns (C-L); there is nothing to import.`);

  // character level (literal, shared by every content type) and the workbook's selected content type
  const shared: Values = {};
  for (const f of schema.fields) if (sharedKeySet.has(f.key)) shared[f.key] = f.default;
  const lv = level(schema, inp, cm.inputs.level, ctx);
  if (lv !== null) shared.level = lv;
  const selRaw = inp.get(cm.inputs.contentType)?.value;
  const selected = typeof selRaw === "string" ? schema.content_types.find((c) => norm(c) === norm(selRaw)) : undefined;
  const contentType = selected && perContent[selected] ? selected : Object.keys(perContent)[0];
  if (selected && !perContent[selected]) ctx.warnings.push({ where: cm.inputs.contentType, message: `The workbook's selected content type "${selected}" has no values; opening on ${contentType}` });

  // companions: levels from CompanionsInput, then the per-content choice (an unowned companion cannot be summoned)
  const companions: CompanionsState = emptyCompanions();
  const cmpSheet = book.sheet(cm.companions.sheet);
  if (!cmpSheet) ctx.warnings.push({ where: cm.companions.sheet, message: `No "${cm.companions.sheet}" sheet: companion levels were not imported (companions stay "None")` });
  else {
    for (const name of schema.companions) {
      const row = cm.companions.rows[name];
      if (row === undefined) continue;
      const cell = cmpSheet.at(row, cm.companions.levelCol);
      const where = ref(cm.companions.levelCol, row);
      if (isBlank(cell)) continue;
      let n: number;
      const v = (cell as Cell).value;
      if (typeof v === "number") n = v;
      else if (typeof v === "string" && norm(v) === "not unlocked") n = 0;
      else if (typeof v === "string" && /^\s*\d+(\.\d+)?\s*$/.test(v)) n = Number(v);
      else {
        ctx.warnings.push({ where, message: `${name}: ${show(cell as Cell)} is not a level (Not unlocked or 1-${COMPANION_MAX_LEVEL}); treated as not unlocked` });
        continue;
      }
      if (!Number.isInteger(n) || n < 0 || n > COMPANION_MAX_LEVEL) {
        ctx.warnings.push({ where, message: `${name}: level ${n} is outside 1-${COMPANION_MAX_LEVEL}; ${n > COMPANION_MAX_LEVEL ? "clamped to " + COMPANION_MAX_LEVEL : "treated as not unlocked"}` });
        n = Math.min(COMPANION_MAX_LEVEL, Math.max(0, Math.round(n)));
      }
      if (n >= 1) companions.levels[name] = n;
    }
  }
  const companionChoices: Record<string, string> = {};
  for (const [ct, vals] of Object.entries(perContent)) {
    const choice = vals.companion_choice;
    if (typeof choice === "string") {
      if (choice !== COMPANION_NONE && !(companions.levels[choice] >= 1)) {
        ctx.warnings.push({ where: ref(columns.get(ct)!, cm.inputs.perContent.companion_choice), message: `${ct}: companion "${choice}" is chosen but not unlocked on the CompanionsInput sheet; set to None`, field: "companion_choice", contentType: ct });
        vals.companion_choice = COMPANION_NONE;
      }
      companionChoices[ct] = String(vals.companion_choice);
    }
  }

  // artifacts: the Star Level + potential lines of EVERY artifact (ArtifactsInput: shared by all content types) and, per content type, the 4 slot rows of the Inputs sheet
  // (= that content type's "Equipped artifacts" in the app)
  const art = schema.artifacts_modelled ? schema.artifacts : undefined;
  const loadouts: Record<string, string[]> = {};
  const equippedArtifacts: EquippedState = {};
  let artifacts: ArtifactsState = {};
  let starsRead = 0;
  let linesRead = 0;
  if (!art) ctx.ignored.push({ where: "ArtifactsInput", message: "This class does not model artifacts in the app; the equipped artifacts were not imported" });
  else {
    artifacts = emptyArtifacts(art);
    const sheet = book.sheet(cm.artifacts.sheet);
    if (!sheet) ctx.warnings.push({ where: cm.artifacts.sheet, message: `No "${cm.artifacts.sheet}" sheet: star levels and potential lines were not imported (default stars used)` });
    else {
      for (const a of art.artifacts) {
        const r = readArtifactRow(art, a.key, sheet, cm, ctx);
        artifacts[a.key] = { ...artifacts[a.key], ...r.entry };
        if (r.starRead) starsRead++;
        linesRead += r.lines;
      }
    }
    const byName = new Map(Object.entries(cm.artifacts.rows).map(([key, v]) => [norm(v.name), key]));
    for (const a of art.artifacts) if (!byName.has(norm(a.name))) byName.set(norm(a.name), a.key);
    for (const [ct, col] of columns) {
      const picked: string[] = []; // slot by slot ("" = empty), like the workbook's rows
      cm.inputs.slotRows.forEach((row, i) => {
        const cell = inp.at(row, col);
        if (isBlank(cell) || norm(String(cell!.value)) === norm(cm.inputs.noneLabel)) return void picked.push(EMPTY_SLOT);
        const key = byName.get(norm(String(cell!.value)));
        if (!key || !artifactInfo(art, key)) {
          ctx.ignored.push({ where: ref(col, row), message: `Slot ${i + 1} (${ct}): unknown artifact ${show(cell as Cell)}; left empty`, contentType: ct });
          return void picked.push(EMPTY_SLOT);
        }
        if (picked.includes(key)) {
          ctx.ignored.push({ where: ref(col, row), message: `Slot ${i + 1} (${ct}): ${art.artifacts.find((a) => a.key === key)?.name} is already in another slot (an artifact counts once); left empty`, contentType: ct });
          return void picked.push(EMPTY_SLOT);
        }
        picked.push(key);
      });
      equippedArtifacts[ct] = normalizeSlots(picked, art);
      const used = picked.filter((k) => k !== EMPTY_SLOT);
      if (used.length) loadouts[ct] = used.map((key) => `${artifactInfo(art, key)?.name ?? key} (${artifacts[key].star ?? NOT_UNLOCKED})`);
    }
    if (sheet) ctx.ignored.push({ where: cm.artifacts.sheet, message: "The workbook has 4 artifact slots, the app 5: the 5th slot of every content type is yours to fill after the import; the computed columns of ArtifactsInput (DPS gains, Equipped?, ...) are never read" });
  }

  // cube gear (PotentialCubes): the same `FormState.cubes` the Cubes tab edits and profiles save
  const cubesSheet = book.sheet(cm.cubes.sheet);
  let cubes: CubesState | undefined;
  let cubeCounts = { pieces: 0, lines: 0, rows: 0 };
  if (!cubesSheet) ctx.warnings.push({ where: cm.cubes.sheet, message: `No "${cm.cubes.sheet}" sheet: the cube gear (rarity, pity, lines) was not imported` });
  else {
    const r = readCubes(cubesSheet, cm, ctx);
    cubes = r.state;
    cubeCounts = r.counts;
  }

  // assemble + normalise like any stored profile
  const base: FormState = { classId: schema.class_id, contentType, shared, perContent, artifacts, ...(art ? { equippedArtifacts } : {}), companions, ...(cubes ? { cubes } : {}) };
  const state = normalizeState(schema, base);
  if (ctx.formulaSkipped)
    ctx.ignored.push({ where: "Inputs", message: `${ctx.formulaSkipped} formula cell${ctx.formulaSkipped === 1 ? " has" : "s have"} no saved result (the file was never opened in Excel); read as blank, default used` });
  const summary: ImportSummary = {
    classId: schema.class_id,
    className: schema.name,
    detected: opts.classChosen ? "chosen" : "title",
    fileTitle: det.title,
    level: typeof shared.level === "number" ? shared.level : null,
    contentType,
    valuesPerContent,
    skippedContentTypes: skipped,
    loadouts,
    starsRead,
    linesRead,
    companionChoices,
    companionLevels: schema.companions.filter((n) => companions.levels[n] >= 1).map((name) => ({ name, level: companions.levels[name] })),
    cubesRead: !!cubesSheet,
    cubePieces: cubeCounts.pieces,
    cubeLines: cubeCounts.lines,
    cubeRows: cubeCounts.rows,
    formulaCellsSkipped: ctx.formulaSkipped,
  };
  return { state, warnings: ctx.warnings, ignored: ctx.ignored, summary };
}

/** One ArtifactsInput row: the Star Level (blank = the workbook's default by rank) and the potential lines 1 / 2 (/ 3 for Legendary artifacts) as rarity + stat. */
function readArtifactRow(art: ArtifactSchema, key: string, sheet: XlsxSheet, cm: ClassMap, ctx: Ctx): { entry: { star: number | null; lines: ArtifactLine[] }; starRead: boolean; lines: number } {
  const info = artifactInfo(art, key)!;
  const name = info.name;
  const row = cm.artifacts.rows[key]?.row;
  const dflt = defaultStarFor(art, key);
  let star = parseStar(dflt);
  let starRead = false;
  if (row !== undefined) {
    const cell = sheet.at(row, cm.artifacts.starCol);
    if (!isBlank(cell)) {
      const s = GENERIC_STAR((cell as Cell).value as Scalar);
      const p = s === null ? ({ ok: false } as const) : parseStar(s);
      if (p.ok) {
        star = p;
        starRead = true;
      } else ctx.warnings.push({ where: ref(cm.artifacts.starCol, row), message: `${name}: star level ${show(cell as Cell)} is not Not Unlocked / 0-5; default (${dflt}) used` });
    }
  }
  const lines: ArtifactLine[] = [blankLine(), blankLine(), blankLine()];
  let read = 0;
  if (row !== undefined) {
    for (let i = 0; i < lineCount(info); i++) {
      const [rc, sc] = cm.artifacts.lineCols[i];
      const statCell = sheet.at(row, sc);
      const rarityCell = sheet.at(row, rc);
      const where = `${ref(rc, row)} / ${ref(sc, row)}`;
      if (isBlank(statCell) || norm(String(statCell!.value)) === norm(NO_STAT)) continue; // no line (a rarity left on its "Rare" default is not a line)
      const stat = STATIC_POTENTIAL_TABLES.stats.find((x) => norm(x) === norm(String(statCell!.value)));
      if (!stat) {
        ctx.warnings.push({ where, message: `${name} line ${i + 1}: unknown potential stat ${show(statCell as Cell)}; the line was left empty` });
        continue;
      }
      let rarity = STATIC_POTENTIAL_TABLES.default_rarity;
      if (!isBlank(rarityCell)) {
        const r = STATIC_POTENTIAL_TABLES.rarities.find((x) => norm(x) === norm(String(rarityCell!.value)));
        if (r) rarity = r;
        else ctx.warnings.push({ where, message: `${name} line ${i + 1}: unknown rarity ${show(rarityCell as Cell)}; ${rarity} used` });
      }
      lines[i] = { rarity, stat };
      read++;
    }
  }
  return { entry: { star: star.ok ? star.value : null, lines }, starRead, lines: read };
}

// ---- cube gear (PotentialCubes) ------------------------------------------------------------------------------------------------------------------
const slug = (s: string) => norm(s).replace(/[\s_]+/g, "-");
const T = CUBE_TABLES;

/** The app's slot id of a workbook slot name (its id "eye-accessory" or its label "Eye accessory", any case / separators); null = unknown. */
export function cubeSlotKey(name: string): string | null {
  const n = slug(name);
  return T.slots.find((s) => s.key === n)?.key ?? T.slots.find((s) => slug(s.label) === n)?.key ?? null;
}
const cubeTypeOf = (name: string): string | null => T.potentialTypes.find((t) => norm(t) === norm(name)) ?? null;
const cubeRarityKey = (name: string): string | null => T.rarities.find((r) => r.key === norm(name))?.key ?? T.rarities.find((r) => norm(r.label) === norm(name))?.key ?? null;
const cubeStatName = (name: string): string | null => T.stats.find((x) => norm(x) === norm(name)) ?? null;

type Num = { kind: "blank" } | { kind: "bad"; shown: string } | { kind: "num"; n: number };
function numberOf(cell: Cell | null): Num {
  if (isBlank(cell)) return { kind: "blank" };
  const v = (cell as Cell).value;
  if (typeof v === "number") return Number.isFinite(v) ? { kind: "num", n: v } : { kind: "bad", shown: String(v) };
  if (typeof v === "string") {
    const p = parseNumber(v.trim().replace(/%$/, "").trim(), "float");
    if (p.ok && p.value !== null) return { kind: "num", n: p.value };
  }
  return { kind: "bad", shown: show(cell as Cell) };
}

/** The PotentialCubes gear table: one row per (slot, potential type), found by the slot / type NAMES in its columns (not by position, so a re-sorted or extended
 *  sheet still imports).  Never throws: unknown names become warnings.  Only rows that hold something are returned (the others are the Cubes tab's blank rows). */
function readCubes(sheet: XlsxSheet, cm: ClassMap, ctx: Ctx): { state: CubesState; counts: { pieces: number; lines: number; rows: number } } {
  const c = cm.cubes;
  const state: CubesState = {};
  const seen = new Map<string, string>(); // row key -> first cell
  let pieces = 0;
  let nLines = 0;
  const lastRow = Math.max(c.lastRow, sheet.maxRow);
  for (let row = c.firstRow; row <= lastRow; row++) {
    const slotCell = sheet.at(row, c.slotCol);
    const typeCell = sheet.at(row, c.typeCol);
    if (isBlank(slotCell) && isBlank(typeCell)) continue;
    // below the sheet's own table (notes, scratch cells): only a recognisable (slot, type) pair counts, anything else is not ours to complain about
    if (row > c.lastRow && !(!isBlank(slotCell) && !isBlank(typeCell) && cubeSlotKey(String(slotCell!.value)) && cubeTypeOf(String(typeCell!.value)))) continue;
    const where = `${ref(c.slotCol, row)}`;
    if (isBlank(slotCell) || isBlank(typeCell)) {
      ctx.warnings.push({ where, message: `Row ${row}: the slot or the potential type is blank; the row was skipped` });
      continue;
    }
    const slot = cubeSlotKey(String(slotCell!.value));
    if (!slot) {
      ctx.warnings.push({ where, message: `Unknown slot ${show(slotCell!)}; the row was skipped` });
      continue;
    }
    const type = cubeTypeOf(String(typeCell!.value));
    if (!type) {
      ctx.warnings.push({ where: ref(c.typeCol, row), message: `${slot}: unknown potential type ${show(typeCell!)} (Potential or Bonus Potential); the row was skipped` });
      continue;
    }
    const key = `${slot}|${type}`;
    const label = `${T.slots.find((s) => s.key === slot)!.label} / ${type}`;
    if (seen.has(key)) {
      ctx.warnings.push({ where, message: `${label} appears twice (also in ${seen.get(key)}); the first row is used` });
      continue;
    }
    seen.set(key, where);

    // rarity (blank = normal)
    let rarity = "normal";
    const rc = sheet.at(row, c.rarityCol);
    if (!isBlank(rc)) {
      const k = cubeRarityKey(String(rc!.value));
      if (k) rarity = k;
      else ctx.warnings.push({ where: ref(c.rarityCol, row), message: `${label}: unknown rarity ${show(rc!)}; normal used` });
    }
    // pity (whole number >= 0; above the track's cap = kept as typed + flagged)
    let pity: number | null = null;
    const pc = numberOf(sheet.at(row, c.pityCol));
    const pw = ref(c.pityCol, row);
    if (pc.kind === "bad") ctx.warnings.push({ where: pw, message: `${label}: pity ${pc.shown} is not a number; 0 used` });
    else if (pc.kind === "num") {
      let n = pc.n;
      if (n < 0) {
        ctx.warnings.push({ where: pw, message: `${label}: pity ${n} is negative; 0 used` });
        n = 0;
      } else if (!Number.isInteger(n)) {
        ctx.warnings.push({ where: pw, message: `${label}: pity ${n} is not a whole number; rounded down to ${Math.floor(n)}` });
        n = Math.floor(n);
      }
      const cap = T.pityCaps[type]?.[rarity] ?? 0;
      if (cap > 0 && n >= cap) ctx.warnings.push({ where: pw, message: `${label}: pity ${n} is not below the ${rarity} cap of ${cap} for ${type} (the upgrade is forced at ${cap} cubes; kept as typed, the engine counts ${cap - 1})` });
      else if (cap === 0 && n > 0) ctx.warnings.push({ where: pw, message: `${label}: ${rarity} is the top tier, so pity ${n} has no meaning (kept as typed, the engine ignores it)` });
      if (n > T.maxPity) ctx.warnings.push({ where: pw, message: `${label}: pity ${n} is above the maximum ${T.maxPity} the calculator accepts` });
      pity = n > 0 ? n : null;
    }
    // lines 1-3
    const lines: GearLine[] = [0, 1, 2].map(() => ({ stat: CUBE_NONE, value: null }));
    c.lineCols.forEach(([sc, vc], i) => {
      const statCell = sheet.at(row, sc);
      const lw = `${ref(sc, row)} / ${ref(vc, row)}`;
      const val = numberOf(sheet.at(row, vc));
      if (isBlank(statCell) || norm(String(statCell!.value)) === norm(CUBE_NONE)) {
        if (val.kind === "num" && val.n !== 0) ctx.ignored.push({ where: lw, message: `${label} line ${i + 1}: value ${val.n} has no stat; ignored` });
        return;
      }
      const stat = cubeStatName(String(statCell!.value));
      if (!stat) {
        ctx.warnings.push({ where: lw, message: `${label} line ${i + 1}: unknown stat ${show(statCell!)}; the line was left empty` });
        return;
      }
      let value: number | null = null;
      if (val.kind === "bad") ctx.warnings.push({ where: lw, message: `${label} line ${i + 1}: value ${val.shown} is not a number; left empty` });
      else if (val.kind === "blank") ctx.warnings.push({ where: lw, message: `${label} line ${i + 1}: ${stat} has no value; left empty` });
      else if (val.n < 0) ctx.warnings.push({ where: lw, message: `${label} line ${i + 1}: value ${val.n} is negative; left empty` });
      else {
        value = val.n;
        if (val.n > T.maxLineValue) ctx.warnings.push({ where: lw, message: `${label} line ${i + 1}: value ${val.n} is above the maximum ${T.maxLineValue} the calculator accepts` });
      }
      if (!(T.statsBySlot[slot] ?? T.stats).includes(stat)) ctx.warnings.push({ where: lw, message: `${label} line ${i + 1}: ${stat} cannot roll on this slot (kept, flagged like the Cubes tab does)` });
      lines[i] = { stat, value };
    });
    const rowState: GearRowState = { ...blankRow(), rarity, pity, lines };
    const nl = lines.filter((l) => l.stat !== CUBE_NONE).length;
    if (nl) pieces++;
    nLines += nl;
    if (isConfigured(rowState)) state[key] = rowState;
  }
  return { state, counts: { pieces, lines: nLines, rows: Object.keys(state).length } };
}

/** Notes with the same text (the same problem in several content-type columns) merged: message + the cells it was found in. */
export interface NoteGroup {
  message: string;
  wheres: string[];
}

export function groupNotes(notes: ImportNote[]): NoteGroup[] {
  const out = new Map<string, NoteGroup>();
  for (const n of notes) {
    const g = out.get(n.message) ?? { message: n.message, wheres: [] };
    g.wheres.push(n.where);
    out.set(n.message, g);
  }
  return [...out.values()];
}

// ---- file -> result ------------------------------------------------------------------------------------------------------------------------------
export interface Loaded {
  book: XlsxBook;
  fileName: string;
  classId: string | null; // detected from the title (null: ask the user)
  title: string | null;
}

/** Read the bytes of a picked/dropped file in the browser and open it as a workbook (throws XlsxError with a friendly message). */
export async function loadWorkbookFile(file: File): Promise<Loaded> {
  const buf = await file.arrayBuffer();
  const book = XlsxBook.open(buf, file.name);
  const { classId, title } = detectClass(book);
  return { book, fileName: file.name, classId, title };
}

/** Profile name that does not collide with a stored profile of the same class (an import never overwrites silently). */
export function uniqueProfileName(base: string, existing: { name: string; state: { classId: string } }[], classId: string): string {
  const taken = new Set(existing.filter((p) => p.state.classId === classId).map((p) => p.name));
  const clean = base.trim().slice(0, 60) || "Excel import";
  if (!taken.has(clean)) return clean;
  for (let i = 2; i < 1000; i++) {
    const suffix = ` (${i})`;
    const cand = clean.slice(0, 60 - suffix.length) + suffix;
    if (!taken.has(cand)) return cand;
  }
  return `${clean.slice(0, 50)} ${Date.now().toString(36)}`;
}
